<?php

declare(strict_types=1);

require_once __DIR__ . '/Database.php';
require_once __DIR__ . '/Auth.php';
require_once __DIR__ . '/AppNavigation.php';
require_once __DIR__ . '/AccessPolicy.php';
require_once __DIR__ . '/ProductionContext.php';
require_once __DIR__ . '/ScheduleAudience.php';

final class ProductionExperience
{
    private const ROUTES=['/production','/schedule','/production/day','/production/edit','/resources','/playbills'];
    public static function handles(string $route):bool{return in_array($route,self::ROUTES,true);}

    public static function render(string $route,string $basePath):never
    {
        Auth::startSession();$db=Database::connect(dirname(__DIR__));$user=Auth::currentUser($db);if(!$user)self::redirect(($basePath?:'').'/login');$_SESSION['production_csrf']??=bin2hex(random_bytes(24));
        if($route==='/production/edit'&&!AccessPolicy::canManageSchedule($user))self::forbidden($basePath,$user);if($_SERVER['REQUEST_METHOD']==='POST'&&$route==='/production/edit')self::handleScheduleEdit($db,$user,$basePath);
        $production=ProductionContext::selected($db,$user);$productionId=$production?(int)$production['id']:0;$schedule=self::schedule($db,$productionId,$user);$announcements=self::announcements($db,$productionId);$channels=self::channels($db,$productionId);$coverage=self::coverage($db,$productionId);$playbill=self::playbill($db,$productionId);$notices=AccessPolicy::canManageSchedule($user)?self::changeNotices($db,$productionId):[];$editItem=null;
        if($route==='/production/edit'){$itemId=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$editItem=self::scheduleItem($db,$productionId,(int)$itemId);if($editItem){$editItem['group_ids']=ScheduleAudience::groupIdsForItem($db,(int)$editItem['id']);$editItem['group_names']=ScheduleAudience::groupNamesForItem($db,(int)$editItem['id']);}}
        $groups=$production&&AccessPolicy::canManageProduction($user)?ScheduleAudience::groups($db,$productionId):[];self::page($route,$basePath,$user,$production,$schedule,$announcements,$channels,$coverage,$playbill,$notices,$editItem,$groups,$db);
    }

    private static function handleScheduleEdit(PDO $db,array $user,string $basePath):never
    {
        if(!AccessPolicy::canManageSchedule($user))self::forbidden($basePath,$user);if(!hash_equals((string)($_SESSION['production_csrf']??''),(string)($_POST['csrf_token']??''))){self::flash('error','Your session token expired. Please try again.');self::redirect($basePath.'/schedule');}$itemId=filter_input(INPUT_POST,'schedule_item_id',FILTER_VALIDATE_INT)?:0;try{self::saveScheduleChange($db,$user,(int)$itemId,$_POST);self::flash('success','Schedule updated and a communication draft was created for the affected audience.');}catch(RuntimeException $e){self::flash('error',$e->getMessage());self::redirect($basePath.'/production/edit?id='.(int)$itemId);}self::redirect($basePath.'/schedule');
    }

    private static function saveScheduleChange(PDO $db,array $user,int $itemId,array $input):void
    {
        if($itemId<1)throw new RuntimeException('That schedule item could not be found.');$selected=ProductionContext::selected($db,$user);if(!$selected)throw new RuntimeException('Select an active production before editing its schedule.');$title=trim((string)($input['title']??''));$location=trim((string)($input['location']??''));$visibility=(string)($input['visibility']??'all');$audienceMode=(string)($input['audience_mode']??'production');$groupIds=(array)($input['group_ids']??[]);$itemType=trim((string)($input['item_type']??'activity'));$startsAt=self::parseLocalDateTime((string)($input['starts_at']??''),'Start time');$endsAt=self::parseOptionalLocalDateTime((string)($input['ends_at']??''),'End time');$familyCallAt=self::parseOptionalLocalDateTime((string)($input['family_call_at']??''),'Family call');
        if($title===''||mb_strlen($title)>190)throw new RuntimeException('Enter a schedule title no longer than 190 characters.');if($location===''||mb_strlen($location)>190)throw new RuntimeException('Enter a location no longer than 190 characters.');if($itemType===''||mb_strlen($itemType)>80)throw new RuntimeException('Enter a valid activity type.');if(!in_array($visibility,['family','staff','all'],true))throw new RuntimeException('Choose a valid audience.');if(!in_array($audienceMode,['production','groups'],true))throw new RuntimeException('Choose a valid schedule targeting mode.');if($endsAt!==null&&$endsAt<=$startsAt)throw new RuntimeException('The end time must be after the start time.');if($familyCallAt!==null&&$familyCallAt>$startsAt)throw new RuntimeException('Family call cannot be later than the activity start time.');$validatedGroups=$audienceMode==='groups'?ScheduleAudience::validateGroupIds($db,(int)$selected['id'],$groupIds):[];if($audienceMode==='groups'&&!$validatedGroups)throw new RuntimeException('Choose at least one production group.');
        $db->beginTransaction();try{$stmt=$db->prepare("SELECT id,production_id,title,starts_at,ends_at,family_call_at,location,visibility,audience_mode,item_type,status FROM schedule_items WHERE id=:id FOR UPDATE");$stmt->execute(['id'=>$itemId]);$before=$stmt->fetch();if(!$before)throw new RuntimeException('That schedule item no longer exists.');if((int)$before['production_id']!==(int)$selected['id'])throw new RuntimeException('That schedule item belongs to a different production workspace.');if($before['status']!=='active')throw new RuntimeException('Cancelled schedule items are retained as history and cannot be edited. Duplicate the item from Calendar if a new call is needed.');$beforeGroups=ScheduleAudience::groupIdsForItem($db,$itemId);sort($beforeGroups);$compareGroups=$validatedGroups;sort($compareGroups);$after=['title'=>$title,'starts_at'=>$startsAt->format('Y-m-d H:i:s'),'ends_at'=>$endsAt?->format('Y-m-d H:i:s'),'family_call_at'=>$familyCallAt?->format('Y-m-d H:i:s'),'location'=>$location,'visibility'=>$visibility,'audience_mode'=>$audienceMode,'item_type'=>$itemType];$changed=$beforeGroups!==$compareGroups;foreach($after as $key=>$value){if(($before[$key]??null)!==$value){$changed=true;break;}}if(!$changed)throw new RuntimeException('Nothing changed, so no update was saved.');$update=$db->prepare('UPDATE schedule_items SET title=:title,starts_at=:starts_at,ends_at=:ends_at,family_call_at=:family_call_at,location=:location,visibility=:visibility,audience_mode=:audience_mode,item_type=:item_type WHERE id=:id');$update->execute($after+['id'=>$itemId]);ScheduleAudience::replaceItemGroups($db,$itemId,(int)$before['production_id'],$audienceMode,$validatedGroups);$audience=ScheduleAudience::audienceMembers($db,(int)$before['production_id'],$visibility,$audienceMode,$validatedGroups);$notice=$db->prepare("INSERT INTO schedule_change_notices (schedule_item_id,production_id,created_by_user_id,audience_scope,audience_count,subject,body,status) VALUES (:item,:production,:actor,:scope,:count,:subject,:body,'draft')");$notice->execute(['item'=>$itemId,'production'=>(int)$before['production_id'],'actor'=>(int)$user['id'],'scope'=>$visibility,'count'=>count($audience),'subject'=>'Schedule update · '.$title,'body'=>self::communicationCopy($after)]);$noticeId=(int)$db->lastInsertId();self::audit($db,(int)$user['id'],'schedule.updated',$itemId,'Updated schedule item and created communication draft.',['before'=>array_intersect_key($before,$after),'before_group_ids'=>$beforeGroups,'after'=>$after,'after_group_ids'=>$validatedGroups,'notice_id'=>$noticeId,'audience_user_ids'=>array_map(static fn(array $row):int=>(int)$row['id'],$audience)]);$db->commit();}catch(Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof RuntimeException)throw $e;throw new RuntimeException('The schedule change could not be saved.');}
    }

    private static function parseLocalDateTime(string $value,string $label):DateTimeImmutable{$d=DateTimeImmutable::createFromFormat('Y-m-d\\TH:i',trim($value));if(!$d)throw new RuntimeException($label.' is required.');return $d;}
    private static function parseOptionalLocalDateTime(string $value,string $label):?DateTimeImmutable{if(trim($value)==='')return null;$d=DateTimeImmutable::createFromFormat('Y-m-d\\TH:i',trim($value));if(!$d)throw new RuntimeException($label.' is not a valid date and time.');return $d;}
    private static function communicationCopy(array $item):string{$start=new DateTimeImmutable($item['starts_at']);$parts=[$item['title'].' has been updated.',$start->format('l, F j \\a\\t g:i A').' at '.$item['location'].'.'];if(!empty($item['family_call_at']))$parts[]='Family call: '.(new DateTimeImmutable($item['family_call_at']))->format('g:i A').'.';$parts[]='Please review the selected production schedule in CTSMD Connect for the latest details.';return implode(' ',$parts);}
    private static function schedule(PDO $db,int $productionId,array $user):array{if($productionId<1)return[];$stmt=$db->prepare("SELECT id,production_id,title,starts_at,ends_at,family_call_at,location,visibility,audience_mode,item_type FROM schedule_items WHERE production_id=:production AND status='active' ORDER BY starts_at ASC");$stmt->execute(['production'=>$productionId]);$rows=$stmt->fetchAll();$visible=[];foreach($rows as $row){if(ScheduleAudience::userCanViewItem($db,$user,$row)){$row['group_names']=$row['audience_mode']==='groups'?ScheduleAudience::groupNamesForItem($db,(int)$row['id']):[];$visible[]=$row;}}return $visible;}
    private static function scheduleItem(PDO $db,int $productionId,int $itemId):?array{if($productionId<1||$itemId<1)return null;$s=$db->prepare("SELECT id,production_id,title,starts_at,ends_at,family_call_at,location,visibility,audience_mode,item_type FROM schedule_items WHERE production_id=:production AND id=:id AND status='active' LIMIT 1");$s->execute(['production'=>$productionId,'id'=>$itemId]);return $s->fetch()?:null;}
    private static function changeNotices(PDO $db,int $productionId):array{if($productionId<1)return[];$s=$db->prepare("SELECT scn.id,scn.schedule_item_id,scn.audience_scope,scn.audience_count,scn.subject,scn.body,scn.status,scn.created_at,CONCAT(u.first_name,' ',u.last_name) creator FROM schedule_change_notices scn LEFT JOIN users u ON u.id=scn.created_by_user_id WHERE scn.production_id=:production ORDER BY scn.created_at DESC,scn.id DESC LIMIT 8");$s->execute(['production'=>$productionId]);return $s->fetchAll();}
    private static function announcements(PDO $db,int $productionId):array{if($productionId<1)return[];$s=$db->prepare("SELECT title,body,context_label,tone,published_at FROM announcements WHERE production_id=:production ORDER BY pinned DESC,published_at DESC LIMIT 5");$s->execute(['production'=>$productionId]);return $s->fetchAll();}
    private static function channels(PDO $db,int $productionId):array{if($productionId<1)return[];$s=$db->prepare("SELECT name,description,channel_type FROM channels WHERE production_id=:production AND archived_at IS NULL ORDER BY sort_order,name");$s->execute(['production'=>$productionId]);return $s->fetchAll();}
    private static function coverage(PDO $db,int $productionId):array{if($productionId<1)return['open_slots'=>0,'shift_count'=>0];$s=$db->prepare("SELECT COUNT(vs.id) shift_count,COALESCE(SUM(GREATEST(vs.required_slots-COALESCE(x.active_signups,0),0)),0) open_slots FROM volunteer_shifts vs LEFT JOIN (SELECT shift_id,COUNT(*) active_signups FROM volunteer_shift_signups WHERE status IN ('signed_up','checked_in','completed') GROUP BY shift_id) x ON x.shift_id=vs.id WHERE vs.production_id=:production");$s->execute(['production'=>$productionId]);return $s->fetch()?:['open_slots'=>0,'shift_count'=>0];}
    private static function playbill(PDO $db,int $productionId):?array{if($productionId<1)return null;$s=$db->prepare("SELECT pb.status,pb.public_slug,p.title,p.season FROM playbills pb JOIN productions p ON p.id=pb.production_id WHERE pb.production_id=:production ORDER BY FIELD(pb.status,'current','draft','archived') LIMIT 1");$s->execute(['production'=>$productionId]);return $s->fetch()?:null;}
    private static function audit(PDO $db,int $actor,string $event,int $id,string $summary,array $meta):void{$s=$db->prepare("INSERT INTO audit_events (actor_user_id,event_type,subject_type,subject_id,summary,metadata_json) VALUES (:actor,:event,'schedule_item',:id,:summary,:meta)");$s->execute(['actor'=>$actor,'event'=>$event,'id'=>$id,'summary'=>$summary,'meta'=>json_encode($meta,JSON_THROW_ON_ERROR)]);}

    private static function page(string $route,string $basePath,array $user,?array $production,array $schedule,array $announcements,array $channels,array $coverage,?array $playbill,array $notices,?array $editItem,array $groups,PDO $db):never
    {
        $url=static fn(string $path):string=>($basePath?:'').$path;$esc=static fn(string $value):string=>htmlspecialchars($value,ENT_QUOTES,'UTF-8');$staff=AccessPolicy::canManageProduction($user);$scheduleManager=AccessPolicy::canManageSchedule($user);$flash=$_SESSION['production_flash']??$_SESSION['production_context_flash']??null;unset($_SESSION['production_flash'],$_SESSION['production_context_flash']);$title=match($route){'/production'=>'Production home','/schedule'=>'Schedule','/production/day'=>'Production day','/production/edit'=>'Edit schedule item','/resources'=>'Resources','/playbills'=>'Playbill',default=>'Production'};$subnav=[['label'=>'Overview','href'=>'/production','active'=>$route==='/production'],['label'=>'Schedule','href'=>'/schedule','active'=>in_array($route,['/schedule','/production/day','/production/edit'],true)]];if($staff)$subnav[]=['label'=>'Groups','href'=>'/production/groups','active'=>false];$subnav[]=['label'=>'Resources','href'=>'/resources','active'=>$route==='/resources'];$subnav[]=['label'=>'Playbill','href'=>'/playbills','active'=>$route==='/playbills'];$next=$schedule[0]??null;
        header('Content-Type: text/html; charset=utf-8');?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#a6192e"><title><?=$esc($title)?> · CTSMD Connect</title><link rel="stylesheet" href="<?=$url('/assets/css/app.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/unified-navigation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/production-implementation.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/production-edit.css')?>"><link rel="stylesheet" href="<?=$url('/assets/css/schedule-create.css')?>"></head><body class="app-body"><div class="unified-shell"><?php AppNavigation::renderSidebar($route,$basePath,$user);?><main class="unified-main"><?php AppNavigation::renderHeader('Production',$title,$basePath,$subnav);?><div class="prod-page"><?php if($flash):?><div class="prod-edit-flash <?=$esc($flash['type'])?>"><?=$esc($flash['message'])?></div><?php endif;?>
<?php if(!$production):?><section class="prod-empty"><b>No active production available</b><p>Activate a production or add this account to an active production to open its workspace.</p></section>
<?php elseif($route==='/production'):?><section class="prod-hero"><div><small>WORKING PRODUCTION</small><h2><?=$esc($production['title'])?></h2><p><?=$esc((string)$production['season'])?> · One home for calls, schedule, communication, volunteer coverage and Playbill access.</p></div><span>Active</span></section><div class="prod-overview-grid"><section class="prod-panel dark"><small>NEXT UP</small><?php if($next):?><h3><?=$esc($next['title'])?></h3><p><?=$esc(date('l, M j · g:i A',strtotime($next['starts_at'])))?></p><p><?=$esc($next['location'])?><?=$next['family_call_at']?' · Family call '.$esc(date('g:i A',strtotime($next['family_call_at']))):''?></p><a href="<?=$url('/production/day')?>">Open production day →</a><?php else:?><h3>Nothing scheduled</h3><p>No upcoming schedule items apply to this account.</p><?php endif;?></section><section class="prod-panel"><small>PRODUCTION PULSE</small><div class="prod-kpis"><span><b><?=count($schedule)?></b><small>visible schedule items</small></span><span><b><?=(int)$coverage['open_slots']?></b><small>open volunteer slots</small></span><span><b><?=count($notices)?></b><small>change drafts</small></span></div></section></div><div class="prod-module-grid"><a href="<?=$url('/schedule')?>"><b>Schedule</b><span>Rehearsals, performances, group calls and locations.</span></a><?php if($staff):?><a href="<?=$url('/production/groups')?>"><b>Production Groups</b><span>Full Cast, Ensemble, Principals, Tech Crew and more.</span></a><?php endif;?><a href="<?=$url('/resources')?>"><b>Resources</b><span>Production information grouped by purpose.</span></a><a href="<?=$url('/channels')?>"><b>Community</b><span><?=count($channels)?> active production channel<?=count($channels)===1?'':'s'?>.</span></a><a href="<?=$url('/volunteer-shifts')?>"><b>Volunteer coverage</b><span><?=(int)$coverage['open_slots']?> open slots.</span></a><a href="<?=$url('/forms')?>"><b>Forms</b><span>Family and volunteer requirements.</span></a><a href="<?=$url('/playbills')?>"><b>Playbill</b><span><?=$playbill?$esc(ucfirst($playbill['status'])):'Not available'?>.</span></a></div>
<?php elseif($route==='/schedule'):?><section class="prod-heading"><div><small><?=$esc(strtoupper($production['title']))?></small><h2>Schedule</h2><p><?=$staff?'Staff see the active production schedule. Group calls resolve to their actual cast/crew audience.':'Only active production-wide calls and group calls relevant to you or your student appear here.'?></p></div><?php if($scheduleManager):?><a class="button" href="<?=$url('/production/schedule/new')?>">Add schedule item</a><?php endif;?></section><div class="prod-schedule-list"><?php if(!$schedule):?><div class="prod-empty"><b>No active schedule items</b></div><?php else:foreach($schedule as $item):$target=$item['audience_mode']==='groups'&&$item['group_names']?implode(' + ',$item['group_names']):'Whole production';?><article><div class="prod-date"><b><?=$esc(date('M',strtotime($item['starts_at'])))?></b><span><?=$esc(date('j',strtotime($item['starts_at'])))?></span></div><div class="prod-schedule-copy"><small><?=$esc(strtoupper($item['item_type']))?> · <?=$esc(strtoupper($target))?></small><h3><?=$esc($item['title'])?></h3><p><?=$esc(date('g:i A',strtotime($item['starts_at'])))?><?=$item['ends_at']?'–'.$esc(date('g:i A',strtotime($item['ends_at']))):''?> · <?=$esc($item['location'])?></p><?php if($item['family_call_at']):?><span>Family call <?=$esc(date('g:i A',strtotime($item['family_call_at'])))?></span><?php endif;?></div><?php if($scheduleManager):?><a class="prod-edit-link" href="<?=$url('/production/edit?id='.(int)$item['id'])?>">Edit →</a><?php endif;?></article><?php endforeach;endif;?></div>
<?php elseif($route==='/production/edit'):?><?php if(!$editItem):?><section class="prod-empty"><b>Active schedule item not found in this production</b><p>Cancelled calls remain available in Calendar history but are not editable here.</p><a class="button" href="<?=$url('/schedule')?>">Back to schedule</a></section><?php else:$audience=ScheduleAudience::audienceMembers($db,(int)$production['id'],(string)$editItem['visibility'],(string)$editItem['audience_mode'],(array)$editItem['group_ids']);?><section class="prod-edit-head"><div><small>SCHEDULE CHANGE</small><h2><?=$esc($editItem['title'])?></h2></div><a href="<?=$url('/schedule')?>">← Schedule</a></section><div class="prod-edit-layout"><form class="prod-edit-form" method="post"><input type="hidden" name="csrf_token" value="<?=$esc((string)$_SESSION['production_csrf'])?>"><input type="hidden" name="schedule_item_id" value="<?=(int)$editItem['id']?>"><label>Title<input name="title" maxlength="190" required value="<?=$esc($editItem['title'])?>"></label><div class="prod-edit-pair"><label>Start<input type="datetime-local" name="starts_at" required value="<?=$esc(date('Y-m-d\TH:i',strtotime($editItem['starts_at'])))?>"></label><label>End<input type="datetime-local" name="ends_at" value="<?=$editItem['ends_at']?$esc(date('Y-m-d\TH:i',strtotime($editItem['ends_at']))):''?>"></label></div><div class="prod-edit-pair"><label>Family call<input type="datetime-local" name="family_call_at" value="<?=$editItem['family_call_at']?$esc(date('Y-m-d\TH:i',strtotime($editItem['family_call_at']))):''?>"></label><label>Location<input name="location" maxlength="190" required value="<?=$esc($editItem['location'])?>"></label></div><div class="prod-edit-pair"><label>Activity type<input name="item_type" maxlength="80" required value="<?=$esc($editItem['item_type'])?>"></label><label>People included<select name="visibility"><option value="family"<?=$editItem['visibility']==='family'?' selected':''?>>Students + guardians</option><option value="staff"<?=$editItem['visibility']==='staff'?' selected':''?>>Staff only</option><option value="all"<?=$editItem['visibility']==='all'?' selected':''?>>All targeted participants</option></select></label></div><fieldset class="sc-target"><legend>Who is this for?</legend><label class="sc-radio"><input type="radio" name="audience_mode" value="production"<?=$editItem['audience_mode']==='production'?' checked':''?>><span><b>Whole production</b></span></label><label class="sc-radio"><input type="radio" name="audience_mode" value="groups"<?=$editItem['audience_mode']==='groups'?' checked':''?>><span><b>Specific production groups</b></span></label><div class="sc-groups"><?php foreach($groups as $group):?><label><input type="checkbox" name="group_ids[]" value="<?=(int)$group['id']?>"<?=in_array((int)$group['id'],(array)$editItem['group_ids'],true)?' checked':''?>><span><b><?=$esc($group['name'])?></b><small><?=(int)$group['member_count']?> active members</small></span></label><?php endforeach;?></div></fieldset><footer><a href="<?=$url('/schedule')?>">Cancel</a><button class="button" type="submit">Save change & create draft</button></footer></form><aside class="prod-impact-card"><small>CURRENT IMPACT</small><b><?=count($audience)?></b><h3>people in this audience</h3><p><?=$editItem['audience_mode']==='groups'?'Current groups: '.$esc(implode(', ',$editItem['group_names'])):'Current target: whole production'?></p></aside></div><?php endif;?>
<?php elseif($route==='/production/day'):?><section class="prod-heading"><div><small><?=$esc(strtoupper($production['title']))?></small><h2>Production day</h2><p>The next active activity that applies to this account.</p></div><a href="<?=$url('/schedule')?>">Full schedule →</a></section><?php if($next):?><div class="prod-day-grid"><section class="prod-panel"><small>NEXT ACTIVITY</small><h3><?=$esc($next['title'])?></h3><div class="prod-day-detail"><span><b>Start</b><?=$esc(date('l, M j · g:i A',strtotime($next['starts_at'])))?></span><span><b>End</b><?=$next['ends_at']?$esc(date('g:i A',strtotime($next['ends_at']))):'Not specified'?></span><span><b>Location</b><?=$esc($next['location'])?></span></div></section><aside class="prod-panel"><small>FAMILY VIEW</small><h3><?=$next['family_call_at']?$esc(date('g:i A',strtotime($next['family_call_at']))):'No family call set'?></h3></aside></div><?php else:?><section class="prod-empty"><b>No upcoming activity</b></section><?php endif;?>
<?php elseif($route==='/resources'):?><section class="prod-heading"><div><small><?=$esc(strtoupper($production['title']))?></small><h2>Production resources</h2></div></section><div class="prod-resource-grid"><a href="<?=$url('/schedule')?>"><i>◷</i><small>SCHEDULE</small><h3>Calls & dates</h3></a><a href="<?=$url('/channels')?>"><i>#</i><small>COMMUNITY</small><h3>Production channels</h3></a><a href="<?=$url('/playbills')?>"><i>▤</i><small>PLAYBILL</small><h3>Digital Playbill</h3></a></div>
<?php else:?><section class="prod-playbill"><small>DIGITAL PLAYBILL</small><h2><?=$esc($production['title'])?></h2><p><?=$esc((string)$production['season'])?></p><?php if($playbill):?><span class="prod-playbill-status"><?=$esc(ucfirst($playbill['status']))?></span><?php else:?><div class="prod-empty"><b>No Playbill record</b></div><?php endif;?></section><?php endif;?></div></main></div><script src="<?=$url('/assets/js/unified-navigation.js')?>"></script></body></html><?php exit;
    }

    private static function forbidden(string $basePath,array $user):never{http_response_code(403);header('Content-Type:text/plain; charset=utf-8');echo 'Schedule management permission is required.';exit;}
    private static function flash(string $type,string $message):void{$_SESSION['production_flash']=['type'=>$type,'message'=>$message];}
    private static function redirect(string $url):never{header('Location: '.$url,true,303);exit;}
}
